const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define GERD reservoir geometry
  const gerd = ee.Geometry.Point([35.09, 11.22]).buffer(5000); // 5km buffer around dam

  // 2. Time periods
  const sep2021Start = '2021-09-01';
  const sep2021End = '2021-09-30';
  const feb2022Start = '2022-02-01';
  const feb2022End = '2022-02-28';

  // 3. Load Sentinel-1 SAR data for September 2021
  let col_sep = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(gerd)
    .filterDate(sep2021Start, sep2021End)
    .filter(ee.Filter.eq('instrumentMode', 'IW'))
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
    .select('VV');

  const size_sep = col_sep.size().getInfo();
  console.log(`September 2021 Images: ${size_sep}`);

  if (size_sep === 0) {
    console.log('No Sentinel-1 data for September 2021.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Load Sentinel-1 SAR data for February 2022
  let col_feb = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(gerd)
    .filterDate(feb2022Start, feb2022End)
    .filter(ee.Filter.eq('instrumentMode', 'IW'))
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
    .select('VV');

  const size_feb = col_feb.size().getInfo();
  console.log(`February 2022 Images: ${size_feb}`);

  if (size_feb === 0) {
    console.log('No Sentinel-1 data for February 2022.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Create median composites
  const img_sep = col_sep.median();
  const img_feb = col_feb.median();

  // 6. Identify water pixels (VV < -15 dB indicates water)
  const water_sep = img_sep.lt(-15);
  const water_feb = img_feb.lt(-15);

  // 7. Calculate water area for September 2021
  const stats_sep = water_sep.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: gerd,
    scale: 1000,
    maxPixels: 1e9
  });

  const waterPixels_sep = stats_sep.get('VV').getInfo();

  if (waterPixels_sep === null || waterPixels_sep === undefined) {
    console.log('Failed to calculate September 2021 water area.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 8. Calculate water area for February 2022
  const stats_feb = water_feb.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: gerd,
    scale: 1000,
    maxPixels: 1e9
  });

  const waterPixels_feb = stats_feb.get('VV').getInfo();

  if (waterPixels_feb === null || waterPixels_feb === undefined) {
    console.log('Failed to calculate February 2022 water area.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 9. Check for valid pixels
  if (waterPixels_sep === 0 && waterPixels_feb === 0) {
    console.log('No valid water pixels detected in either period.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 10. Calculate actual areas (pixels * 1000m * 1000m / 1e6 for km²)
  const area_sep_km2 = (waterPixels_sep * 1.0);
  const area_feb_km2 = (waterPixels_feb * 1.0);

  console.log(`Sep 2021 Water Pixels: ${waterPixels_sep.toFixed(0)}`);
  console.log(`Feb 2022 Water Pixels: ${waterPixels_feb.toFixed(0)}`);
  console.log(`Sep 2021 Relative Area: ${area_sep_km2.toFixed(1)}`);
  console.log(`Feb 2022 Relative Area: ${area_feb_km2.toFixed(1)}`);

  // 11. Compare water levels
  if (area_feb_km2 < area_sep_km2) {
    console.log('Water level DECREASED in February 2022.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Water level did NOT decrease in February 2022.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
